+    ret = xmlAllocOutputBuffer(encoder);
     if (ret == NULL) {
         xmlFree(unescaped);
-        xmlCharEncCloseFunc(encoder);
         return(NULL);
     }

@@ -1589,6 +1544,8 @@ __xmlOutputBufferCreateFilename(const char *URI,
  * TODO: currently if compression is set, the library only support
